 * also the raw URL and the markdown that renders it inline.
 * ...
 */
export function publishedFileFor(repo: string, branch: string, target: string): {
  target: string; blob_url: string; raw_url?: string; markdown?: string;
} {
  const blob_url = blobUrlFor(repo, branch, target);
